create or replace function public.epic_unified_notes_add(p_confirmation text,p_note_text text,p_show_in_readiness boolean,p_author text) returns setof public.epic_unified_notes language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return query insert into public.epic_unified_notes(confirmation_code,note_text,note_scope,source,visible_in_readiness,author_name) values(upper(btrim(p_confirmation)),btrim(p_note_text),'reservation','c360',coalesce(p_show_in_readiness,false),p_author) returning *; end $$;